  } catch (error) {
    console.error('Error posting message:', error);
  }
}

// Set up event listeners
sendButton.addEventListener('click', handleSubmit);
messageInput.addEventListener('keypress', (e) => {
  if (e.key === 'Enter') handleSubmit(e);
});

