  "dependencies": {
    "@electric-sql/pglite": "^0.1.0",
    "cors": "^2.8.5",
    "express": "^4.18.2"
  },
  "devDependencies": {
    "concurrently": "^8.2.0",
    "vite": "^4.4.9"
  }
